26	import {
27	  ProdutoSetorUnidadeDialog,
28	  type ProdutoEdit,
29	} from './ProdutoSetorUnidadeDialog';
30	
31	/**
32	 * Matrix de Visibilidade Produto × Loja.
33	 *
34	 * Admin-only. Carrega produtos ativos de `produtos_master` e lojas ativas,
35	 * cruza com `produto_loja_visibility` e renderiza um grid de checkboxes.
36	 * Controla quais produtos aparecem na aba Contagem de cada loja.
37	 *
38	 * Recuperado do commit 41a96c4 (perdido no refactor FSD). A view
39	 * `vw_produtos_estoque_lojas` que alimenta a contagem JÁ faz INNER JOIN
40	 * com esta tabela, então as mudanças refletem direto na contagem.
41	 */
42	
43	interface ProductVisibilityMatrixProps {
44	  onBack: () => void;
45	}
46	
47	interface Produto {
48	  id: number;
49	  nome: string;
50	  setor: string;
51	  codigo_interno: number | null;
52	  unidade_medida: string | null;
53	}
54	
55	interface Loja {
56	  id: number;
57	  nome: string;
58	}
59	
60	const visKey = (prodId: number, lojaId: number) => `${prodId}_${lojaId}`;
61	
62	const setorEmoji = (nome: string): string => {
63	  const n = (nome || '').toLowerCase();
64	  if (n.includes('camara fria') || n.includes('câmara fria')) return '❄️';
65	  if (n === 'insumos' || n.includes('estoque insumos')) return '🥄';
66	  if (n === 'mercearia') return '🛒';
67	  if (n === 'embalagens') return '📦';
68	  if (n === 'limpeza') return '🧼';
69	  if (n === 'natal') return '🎅';
70	  if (n === 'todos') return '🌎';
71	  if (n === 'sem setor') return '❓';
72	  return '🏷️';
73	};
74	
75	export function ProductVisibilityMatrix({
76	  onBack,
77	}: ProductVisibilityMatrixProps) {
78	  const [loading, setLoading] = useState(false);
79	  const [saving, setSaving] = useState(false);
80	  const [allProducts, setAllProducts] = useState<Produto[]>([]);
81	  const [lojas, setLojas] = useState<Loja[]>([]);
82	  const [officialSetoresList, setOfficialSetoresList] = useState<string[]>([]);
83	  const [visibility, setVisibility] = useState<Record<string, boolean>>({});
84	  const [initialVisibility, setInitialVisibility] = useState<
85	    Record<string, boolean>
86	  >({});
87	  const [searchTerm, setSearchTerm] = useState('');
88	  const [setorSelecionado, setSetorSelecionado] = useState('Todos');
89	
90	  const [selectedIds, setSelectedIds] = useState<Set<number>>(new Set());
91	  const [setorDestino, setSetorDestino] = useState('');
92	  const [showSetorManager, setShowSetorManager] = useState(false);
93	  const [editandoProduto, setEditandoProduto] = useState<ProdutoEdit | null>(
94	    null,
95	  );
96	  const [movendoMassa, setMovendoMassa] = useState(false);
97	  const { setores: setoresCanonicos, moverItensSelecionados } = useSetores();
98	
99	  useEffect(() => {
100	    loadData();
101	  }, []);
102	
103	  // Recarrega setores E produtos (reflete mudanças feitas no SetorManager,
104	  // ex.: mover-tudo de um setor) SEM tocar na visibilidade não salva.
105	  const reloadSetores = async () => {
106	    const [setoresRes, produtosRes] = await Promise.all([
107	      supabase.from('setores').select('nome, ativo').eq('ativo', true).order('nome'),
108	      supabase
109	        .from('produtos_master')
110	        .select('id, nome, setor, codigo_interno, ativo, unidade_medida')
111	        .eq('ativo', true)
112	        .order('nome'),
113	    ]);
114	    if (setoresRes.error || produtosRes.error) return;
115	
116	    const officialSetores = ((setoresRes.data as any[]) || [])
117	      .map((s: any) => s.nome as string)
118	      .filter((n: string) => !!n && n.trim() !== '');
119	    const officialMap = new Map<string, string>();
120	    officialSetores.forEach((n) => officialMap.set(n.trim().toUpperCase(), n));
121	
122	    const prods: Produto[] = ((produtosRes.data as any[]) || []).map((p: any) => {
123	      const raw = (p.setor || '').trim();
124	      const canonical = raw ? officialMap.get(raw.toUpperCase()) : undefined;
125	      return {
126	        id: p.id,
127	        nome: p.nome,
128	        setor: canonical ?? 'SEM SETOR',
129	        codigo_interno: p.codigo_interno,
130	        unidade_medida: p.unidade_medida,
131	      };
132	    });
133	
134	    setOfficialSetoresList(officialSetores);
135	    setAllProducts(prods);
136	  };
137	
138	  const loadData = async () => {
139	    setLoading(true);
140	    try {
141	      // 1. Setores oficiais (fonte da verdade — mesma tabela usada na Contagem)
142	      const { data: setoresData, error: setoresError } = await supabase
143	        .from('setores')
144	        .select('nome, ativo')
145	        .eq('ativo', true)
146	        .order('nome');
147	      if (setoresError) throw setoresError;
148	      const officialSetores = (setoresData || [])
149	        .map((s: any) => s.nome as string)
150	        .filter((n: string) => !!n && n.trim() !== '');
151	      // Map normalizado (UPPERCASE + trim) → nome canônico para match case-insensitive
152	      const officialMap = new Map<string, string>();
153	      officialSetores.forEach((n) => {
154	        officialMap.set(n.trim().toUpperCase(), n);
155	      });
156	
157	      // 2. Produtos ativos
158	      const { data: productsData, error: productsError } = await supabase
159	        .from('produtos_master')
160	        .select('id, nome, setor, codigo_interno, ativo, unidade_medida')
161	        .eq('ativo', true)
162	        .order('nome');
163	      if (productsError) throw productsError;
164	
165	      // 3. Lojas ativas
166	      const { data: lojasData, error: lojasError } = await supabase
167	        .from('lojas')
168	        .select('id, nome')
169	        .or('ativo.eq.true,ativo.is.null')
170	        .order('id');
171	      if (lojasError) throw lojasError;
172	
173	      // 4. Visibilidade (paginado — pode ultrapassar 1000 linhas)
174	      const visAll: {
175	        produto_master_id: number;
176	        loja_id: number;
177	        ativo: boolean;
178	      }[] = [];
179	      let offset = 0;
180	      const PAGE = 1000;
181	      while (true) {
182	        const { data: batch, error: batchErr } = await supabase
183	          .from('produto_loja_visibility' as any)
184	          .select('produto_master_id, loja_id, ativo')
185	          .range(offset, offset + PAGE - 1);
186	        if (batchErr) throw batchErr;
187	        if (!batch || batch.length === 0) break;
188	        visAll.push(...(batch as any));
189	        if (batch.length < PAGE) break;
190	        offset += PAGE;
191	      }
192	
193	      // Normaliza setor de cada produto pro nome canônico (case-insensitive).
194	      // Produtos com setor inválido (NULL, "Todos", etc) recebem 'SEM SETOR' em vez de serem descartados.
195	      const prods: Produto[] = (productsData || []).map((p: any) => {
196	        const raw = (p.setor || '').trim();
197	        const canonical = raw ? officialMap.get(raw.toUpperCase()) : undefined;
198	        return {
199	          id: p.id,
200	          nome: p.nome,
201	          setor: canonical ?? 'SEM SETOR',
202	          codigo_interno: p.codigo_interno,
203	          unidade_medida: p.unidade_medida,
204	        };
205	      });
206	
207	      setAllProducts(prods);
208	      setOfficialSetoresList(officialSetores);
209	      setLojas(
210	        (lojasData || []).map((l: any) => ({ id: l.id, nome: l.nome })),
211	      );
212	
213	      const visMap: Record<string, boolean> = {};
214	      visAll.forEach((v) => {
215	        visMap[visKey(v.produto_master_id, v.loja_id)] = v.ativo;
216	      });
217	      setVisibility(visMap);
218	      setInitialVisibility({ ...visMap });
219	    } catch (error) {
220	      handleError(error, {
221	        domain: 'produtos',
222	        operation: 'loadVisibilityMatrix',
223	        showToast: false,
224	      });
225	      toast({
226	        title: 'Erro ao carregar matrix de visibilidade',
227	        variant: 'destructive',
228	      });
229	    } finally {
230	      setLoading(false);
231	    }
232	  };
233	
234	  const setores = useMemo(() => {
235	    const hasOrfaos = allProducts.some((p) => p.setor === 'SEM SETOR');
236	    return [
237	      'Todos',
238	      ...(hasOrfaos ? ['SEM SETOR'] : []),
239	      ...officialSetoresList,
240	    ];
241	  }, [officialSetoresList, allProducts]);
242	
243	  const filteredProducts = useMemo(() => {
244	    const term = searchTerm.trim().toLowerCase();
245	    return allProducts.filter((p) => {
246	      const matchesSearch =
247	        !term ||
248	        p.nome.toLowerCase().includes(term) ||
249	        (p.codigo_interno?.toString() || '').includes(term);
250	      const matchesSetor =
251	        setorSelecionado === 'Todos' || p.setor === setorSelecionado;
252	      return matchesSearch && matchesSetor;
253	    });
254	  }, [allProducts, searchTerm, setorSelecionado]);
255	
256	  const groupedProducts = useMemo(() => {
257	    const groups: Record<string, Produto[]> = {};
258	    filteredProducts.forEach((p) => {
259	      if (!groups[p.setor]) groups[p.setor] = [];
260	      groups[p.setor].push(p);
261	    });
262	    return groups;
263	  }, [filteredProducts]);
264	
265	  const toggleCell = (prodId: number, lojaId: number) => {
266	    const key = visKey(prodId, lojaId);
267	    setVisibility((prev) => ({ ...prev, [key]: !prev[key] }));
268	  };
269	
270	  const selectAllForStore = (lojaId: number) => {
271	    setVisibility((prev) => {
272	      const next = { ...prev };
273	      filteredProducts.forEach((p) => {
274	        next[visKey(p.id, lojaId)] = true;
275	      });
276	      return next;
277	    });
278	  };
279	
280	  const deselectAllForStore = (lojaId: number) => {
281	    setVisibility((prev) => {
282	      const next = { ...prev };
283	      filteredProducts.forEach((p) => {
284	        next[visKey(p.id, lojaId)] = false;
285	      });
286	      return next;
287	    });
288	  };
289	
290	  const selectSectorForStore = (setor: string, lojaId: number) => {
291	    setVisibility((prev) => {
292	      const next = { ...prev };
293	      filteredProducts
294	        .filter((p) => p.setor === setor)
295	        .forEach((p) => {
296	          next[visKey(p.id, lojaId)] = true;
297	        });
298	      return next;
299	    });
300	  };
301	
302	  const deselectSectorForStore = (setor: string, lojaId: number) => {
303	    setVisibility((prev) => {
304	      const next = { ...prev };
305	      filteredProducts
306	        .filter((p) => p.setor === setor)
307	        .forEach((p) => {
308	          next[visKey(p.id, lojaId)] = false;
309	        });
310	      return next;
311	    });
312	  };
313	
314	  const hasChanges = useMemo(
315	    () => JSON.stringify(visibility) !== JSON.stringify(initialVisibility),
316	    [visibility, initialVisibility],
317	  );
318	
319	  const changedCount = useMemo(() => {
320	    const keys = new Set([
321	      ...Object.keys(visibility),
322	      ...Object.keys(initialVisibility),
323	    ]);
324	    let count = 0;
325	    keys.forEach((k) => {
326	      if ((visibility[k] ?? false) !== (initialVisibility[k] ?? false))
327	        count++;
328	    });
329	    return count;
330	  }, [visibility, initialVisibility]);
331	
332	  const handleSave = async () => {
333	    setSaving(true);
334	    try {
335	      const keys = new Set([
336	        ...Object.keys(visibility),
337	        ...Object.keys(initialVisibility),
338	      ]);
339	      const upserts: {
340	        produto_master_id: number;
341	        loja_id: number;
342	        ativo: boolean;
343	      }[] = [];
344	
345	      keys.forEach((k) => {
346	        const newVal = visibility[k] ?? false;
347	        const oldVal = initialVisibility[k] ?? false;
348	        if (newVal !== oldVal) {
349	          const [prodId, lojaId] = k.split('_').map(Number);
350	          upserts.push({
351	            produto_master_id: prodId,
352	            loja_id: lojaId,
353	            ativo: newVal,
354	          });
355	        }
356	      });
357	
358	      if (upserts.length === 0) {
359	        toast({ title: 'Nenhuma alteração para salvar' });
360	        setSaving(false);
361	        return;
362	      }
363	
364	      // Chunking para lotes grandes
365	      for (let i = 0; i < upserts.length; i += 100) {
366	        const batch = upserts.slice(i, i + 100);
367	        const { error } = await supabase
368	          .from('produto_loja_visibility' as any)
369	          .upsert(batch as any, { onConflict: 'produto_master_id,loja_id' });
370	        if (error) throw error;
371	      }
